parameters.jsonBody:
={
  "to": "{{ $json.targetUserId }}",
  "messages": [
    {
      "type": "flex",
      "altText": "🎉 您的專屬優惠商品推薦：{{ $json.cardTitle }}",
      "contents": {
        "type": "bubble",
        "hero": {
          "type": "image",
          "url": "{{ $json.imageUrl }}",
          "size": "full",
          "aspectRatio": "20:13",
          "aspectMode": "cover",
          "action": {
            "type": "uri",
            "uri": "{{ $json.actionUrl }}"
          }
        },
        "body": {
          "type": "box",
          "layout": "vertical",
          "contents": [
            {
              "type": "text",
              "text": "{{ $json.cardTitle }}",
              "weight": "bold",
              "size": "xl"
            },
            {
              "type": "text",
              "text": "{{ $json.cardSubtitle }}",
              "size": "sm",
              "color": "#999999",
              "margin": "md"
            },
            {
              "type": "box",
              "layout": "baseline",
              "margin": "lg",
              "contents": [
                {
                  "type": "text",
                  "text": "{{ $json.cardPrice }}",
                  "weight": "bold",
                  "size": "xxl",
                  "color": "#FF334B",
                  "flex": 0
                },
                {
                  "type": "text",
                  "text": "{{ $json.originalPrice }}",
                  "size": "sm",
                  "color": "#aaaaaa",
                  "margin": "md",
                  "decoration": "line-through",
                  "flex": 0
                }
              ]
            }
          ]
        },
        "footer": {
          "type": "box",
          "layout": "vertical",
          "spacing": "sm",
          "contents": [
            {
              "type": "button",
              "style": "primary",
              "height": "sm",
              "color": "#06C755",
              "action": {
                "type": "uri",
                "label": "🛍️ 立即前往搶購",
                "uri": "{{ $json.actionUrl }}"
              }
            }
          ],
          "flex": 0
        }
      }
    }
  ]
}
